export const RAW_combination_RowApproval = `<template>
  <div>
    <div style="margin-bottom: 12px; color: #909399; font-size: 13px;">
      每行「通过 / 驳回」按钮通过声明式 operate 列 btns 配置；驳回需在弹窗中填写原因；已处理行的按钮自动隐藏
    </div>
    <es-table
      :data-source="data"
      :columns="columns"
      :options="options"
    />
  </div>
</template>

<script lang="jsx">
/**
 * 行审批（组合）—— 声明式 operate 列 btns + 行级状态流转 + 驳回弹窗
 *
 * 关键点：
 *   1. operate 列用声明式 btns 配置：{ name, type, hidden, clickEvent }，
 *      key/prop 为 'operate' 且不写 render 时，EsTable 自动渲染按钮
 *   2. btns 的 hidden 支持函数 (row) => boolean，据行状态动态显隐
 *   3. clickEvent(row) 拿到当前行；驳回复用 useDialog 收集原因后回写状态
 */
import { defineComponent, reactive } from '@vue/composition-api'
import { useDialog } from '@es-plus/vue2'
import { Message } from 'element-ui'

const statusTag = { 待审批: 'warning', 已通过: 'success', 已驳回: 'danger' }

export default defineComponent({
  name: 'CombinationRowApproval',
  setup() {
    const data = reactive([
      { id: 1, applicant: '张三', type: '报销', amount: 1280, status: '待审批', reason: '' },
      { id: 2, applicant: '李四', type: '请假', amount: 0, status: '待审批', reason: '' },
      { id: 3, applicant: '王五', type: '采购', amount: 8600, status: '已通过', reason: '' }
    ])
    const dialog = useDialog()

    const approve = (row) => {
      row.status = '已通过'
      Message.success(\`已通过 \${row.applicant} 的申请\`)
    }

    const reject = (row) => {
      let reason = ''
      dialog({
        title: \`驳回 - \${row.applicant}\`,
        width: '420px',
        // eslint-disable-next-line no-unused-vars -- h 供 JSX 使用（setup 内无 this.\$createElement）
        render: (h) => (
          <el-input
            type="textarea"
            rows={3}
            placeholder="请填写驳回原因"
            value={reason}
            on-input={(v) => { reason = v }}
          />
        ),
        configBtn: [
          { name: '取消', key: 'cancel', click: (_, { close }) => close() },
          {
            name: '确认驳回',
            type: 'danger',
            key: 'confirm',
            click: (_, { close }) => {
              if (!reason.trim()) {
                Message.warning('请填写驳回原因')
                return
              }
              row.status = '已驳回'
              row.reason = reason
              Message.success('已驳回')
              close()
            }
          }
        ]
      })
    }

    const columns = [
      { prop: 'id', label: 'ID', width: 70 },
      { prop: 'applicant', label: '申请人', width: 110 },
      { prop: 'type', label: '类型', width: 100 },
      {
        prop: 'amount',
        label: '金额',
        width: 120,
        render: (h, { row }) => <span>{row.amount ? \`¥\${row.amount}\` : '—'}</span>
      },
      {
        prop: 'status',
        label: '状态',
        width: 110,
        render: (h, { row }) => (
          <el-tag type={statusTag[row.status]} size="small">{row.status}</el-tag>
        )
      },
      { prop: 'reason', label: '驳回原因', render: (h, { row }) => <span>{row.reason || '—'}</span> },
      {
        prop: 'operate',
        label: '操作',
        width: 140,
        btns: [
          { name: '通过', type: 'primary', hidden: (row) => row.status !== '待审批', clickEvent: approve },
          { name: '驳回', type: 'danger', hidden: (row) => row.status !== '待审批', clickEvent: reject }
        ]
      }
    ]

    const options = { border: true }

    return { data, columns, options }
  }
})
</script>
`
export const RAW_combination_StepForm = `<template>
  <div style="max-width: 760px;">
    <el-steps :active="step" finish-status="success" align-center style="margin-bottom: 28px;">
      <el-step title="账户信息" />
      <el-step title="企业资料" />
      <el-step title="核对提交" />
    </el-steps>

    <!-- 用 v-show 保留已填表单实例，切换步骤不丢数据 -->
    <div v-show="step === 0">
      <es-form ref="form0" :model="model" :form-item-list="step0Items" :layout-form-props="layout" :rules="step0Rules" />
    </div>
    <div v-show="step === 1">
      <es-form ref="form1" :model="model" :form-item-list="step1Items" :layout-form-props="layout" :rules="step1Rules" />
    </div>

    <div v-if="step === 2" style="padding: 4px 8px; line-height: 2.2;">
      <div>账号：<b>{{ model.account }}</b></div>
      <div>邮箱：<b>{{ model.email }}</b></div>
      <div>企业名称：<b>{{ model.company }}</b></div>
      <div>统一社会信用代码：<b>{{ model.creditCode }}</b></div>
      <div>所属行业：<b>{{ industryLabel }}</b></div>
    </div>

    <div style="text-align: right; margin-top: 24px;">
      <el-button v-if="step > 0" @click="prev">上一步</el-button>
      <el-button v-if="step < 2" type="primary" @click="next">下一步</el-button>
      <el-button v-if="step === 2" type="success" @click="submit">提交</el-button>
    </div>
  </div>
</template>

<script lang="jsx">
/**
 * 分步表单（组合）—— el-steps + 多个 EsForm 分步校验 + 核对提交
 *
 * 关键点：
 *   1. 多个 EsForm 共用一个 model，各步用独立 form-item-list 与 rules
 *   2. 用模板 ref（form0/form1）拿到 EsForm 实例，「下一步」前 await validate() 当前步
 *   3. v-show 保留表单实例，切换步骤不清空已填数据；末步用 v-if 渲染核对信息
 */
import { defineComponent, reactive, ref, computed } from '@vue/composition-api'
import { Message } from 'element-ui'

const industryOptions = [
  { label: '互联网', value: 'internet' },
  { label: '制造业', value: 'manufacturing' },
  { label: '金融', value: 'finance' }
]

export default defineComponent({
  name: 'CombinationStepForm',
  setup() {
    const step = ref(0)
    const form0 = ref(null)
    const form1 = ref(null)

    const model = reactive({
      account: '',
      email: '',
      company: '',
      creditCode: '',
      industry: ''
    })

    const step0Items = [
      { prop: 'account', label: '账号', span: 24, formtype: 'Input', attrs: { placeholder: '请输入账号' } },
      { prop: 'email', label: '邮箱', span: 24, formtype: 'Input', attrs: { placeholder: '请输入邮箱' } }
    ]
    const step0Rules = {
      account: [{ required: true, message: '请输入账号', trigger: 'blur' }],
      email: [
        { required: true, message: '请输入邮箱', trigger: 'blur' },
        { type: 'email', message: '邮箱格式不正确', trigger: 'blur' }
      ]
    }

    const step1Items = [
      { prop: 'company', label: '企业名称', span: 24, formtype: 'Input', attrs: { placeholder: '请输入企业名称' } },
      { prop: 'creditCode', label: '信用代码', span: 24, formtype: 'Input', attrs: { placeholder: '统一社会信用代码' } },
      {
        prop: 'industry',
        label: '所属行业',
        span: 24,
        formtype: 'Select',
        attrs: { style: 'width:100%', placeholder: '请选择行业' },
        dataOptions: industryOptions
      }
    ]
    const step1Rules = {
      company: [{ required: true, message: '请输入企业名称', trigger: 'blur' }],
      creditCode: [{ required: true, message: '请输入信用代码', trigger: 'blur' }],
      industry: [{ required: true, message: '请选择行业', trigger: 'change' }]
    }

    const layout = { fromLayProps: { labelWidth: '120px', size: 'small' } }

    const industryLabel = computed(
      () => industryOptions.find((o) => o.value === model.industry)?.label || '—'
    )

    const next = async () => {
      const formRef = step.value === 0 ? form0.value : form1.value
      const ok = await formRef?.validate()
      if (ok) step.value += 1
    }
    const prev = () => { step.value -= 1 }
    const submit = () => {
      Message.success('提交成功')
      step.value = 0
    }

    return {
      step, form0, form1, model,
      step0Items, step0Rules, step1Items, step1Rules,
      layout, industryLabel, next, prev, submit
    }
  }
})
</script>
`
